    .withExec(["bun", "run", "tools:test"])
    .stdout();
}

/**
 * Production build. Returns the built artifacts (`dist/` client bundle and
 * `server/` SSR output) as a Directory you can `export`.
 */
@func()
build(
  @argument({ defaultPath: "/", ignore: SOURCE_IGNORE })
  source: Directory,
): Directory {
  const built = this.install(source)
    .withExec(["bun", "run", "tools:build"])
    .withExec(["bun", "run", "build"]);
  return dag
    .directory()
    .withDirectory("dist", built.directory("/app/dist"))
    .withDirectory("server", built.directory("/app/server"));
}

/**
 * Package a release tarball — mirrors the `release.yml` packaging step.
 * Returns the `.tar.gz` File; `export` it to disk or attach it to a release.
 */
@func()
package(
  @argument({ defaultPath: "/", ignore: SOURCE_IGNORE })
  source: Directory,
  version = "dev",
): File {
  const tarball = `release/twyne-${version}.tar.gz`;
  return this.install(source)
    .withExec(["bun", "run", "tools:build"])
    .withExec(["bun", "run", "build"])
    .withExec([
      "sh",
      "-c",
      `mkdir -p release && tar --exclude=./node_modules --exclude=./release --exclude=./.git -czf ${tarball} .`,
    ])
    .file(`/app/${tarball}`);
}

/**
 * Full CI gate.
 *
 * Lint, typecheck, and unit tests read the same installed source but do not
 * share output directories, so Dagger can evaluate them in parallel.
 * Packaging remains behind all three quality gates: it performs the Qwik
 * client and SSR builds, whose generated manifests/output must stay
 * serialized until those directories are explicitly isolated.
 */
@func()
async all(
  @argument({ defaultPath: "/", ignore: SOURCE_IGNORE })
  source: Directory,
): Promise<string> {
